#include &lt;iostream&gt;

class NumberPrinter {
public:
    void print(int x) {
        std::cout &lt;&lt; x &lt;&lt; std::endl;
    }

    void printRange(int from, int to) {
        for (int i = from; i &lt;= to; ++i) {
            std::cout &lt;&lt; i &lt;&lt; std::endl;
        }
    }
};



